SELECT 


  m.room_id = #{roomId}
  AND (m.visible_to_user_id IS NULL OR m.visible_to_user_id = #{viewerId})
  AND m.id < #{cursorId}

ORDER BY m.id DESC
LIMIT #{size}

SELECT 

WHERE m.room_id = #{roomId}
ORDER BY m.id DESC
LIMIT #{limit}

SELECT 

WHERE m.room_id = #{roomId}
  AND (m.role = 'ASSISTANT' OR m.mode = 'AI')
ORDER BY m.id DESC
LIMIT #{limit}
